#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ReciprocalLength; 10] = [
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseMeter),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseCentimeter),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseMillimeter),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseMile),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseYard),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseFoot),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseUsSurveyFoot),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseInch),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseMil),
        ReciprocalLength::const_new(1234.5, ReciprocalLengthUnit::InverseMicroinch),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ReciprocalLengthUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ReciprocalLength::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ReciprocalLengthUnit::ALL {
            assert_eq!(
                ReciprocalLength::const_new(v, unit).as_base().to_bits(),
                ReciprocalLength::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ReciprocalLength::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ReciprocalLength::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ReciprocalLengthUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ReciprocalLength::from_base(0.0).auto_unit().unit,
        ReciprocalLengthUnit::InverseMeter
    );
}

